import{_ as t,c as a,a2 as e,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"交易真的是一个反复试错的过程吗？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易是反复试错理解/试错的前提是这东西值的一试.md","filePath":"stock/交易是反复试错理解/试错的前提是这东西值的一试.md"}'),r={name:"stock/交易是反复试错理解/试错的前提是这东西值的一试.md"};function s(n,p,_,c,i,d){return o(),a("div",null,p[0]||(p[0]=[e('<h1 id="交易真的是一个反复试错的过程吗" tabindex="-1">交易真的是一个反复试错的过程吗？ <a class="header-anchor" href="#交易真的是一个反复试错的过程吗" aria-label="Permalink to &quot;交易真的是一个反复试错的过程吗？&quot;">​</a></h1><p>确实是这样，<strong>不仅要试，而且要认。</strong></p><p>所以，说到这里不得不吐槽一下a股的交易制度，交易这个事情，原则上就是我看到了一个东西不错，尝试一下，结果行就赚，不行我马上就跑，打的赢就打，打不赢就走，就是这么个事。</p><p>但是在a股呢，不让走，错了，不让改，明天再改，然后明天再给你来个低开，直接关门打狗。</p><p>所以从交易制度上来说，期货比股票强，不仅是双向交易，而是t0，所以交易者既可以做日内，也可以做趋势，唯一的缺陷就是盘子小，属于小众的交易模式。</p><p>大a最擅长关门打狗 关于止损会导致本金越来越少的事情，我觉得要换个角度去思考，止损应当看做是交易的成本而非交易的损失。</p><p>这两个概念完全不一样。</p><p>如果你把止损看做是交易的损失，那么就会陷入一种交易陷阱，那就是寻找确定性。是个人都会讨厌损失，所以一旦交易出错，心里就会想着又亏钱了，从而心烦意乱，并且在连续出错后，会对下单产生恐惧，因为害怕止损。</p><p>但如果把止损看做是成本呢，那么就可以理解到任何事情都有成本，是正常可接受的。比如一个人要上班，那么除了要付出时间之外，一天三顿饭就是他上班的成本，这个钱必须要花，因为花了这个钱才有可能不被饿死继续上班，回归到交易上来，止损的钱必须要给，只有给了止损交易者才有可能不被爆仓有本金继续交易下去。</p><p>到这里，有些人就会说，那我学巴菲特价值投资不就可以不止损了？</p><p>实际情况是，巴菲特也会止损，并且很强调止损的重要性，举个例子说明：</p><p>在2020年3月初，巴菲特抄底了美国的四大航空股，同时在3月中旬，巴菲特明确表态说不会卖出航空股，不过在随后不久的股东大会上，他却说清仓了美国的四大航空股。关于清仓航空股的原因，巴菲特给出了自己的解释：“疫情改变了他对航空公司的看法，不清楚未来三四年是否会像去年那样坐飞机，伯克希尔已经卖出了美国四大航空公司（美国航空、达美航空、美国西南航空、联合航空）。”</p><p>说完了认，这里还要重点说明一下试的问题，<strong>不管是任何东西，试错的前提是，这个东西值得试一试。</strong></p><p>比方说，榴莲很多人爱吃但又很多人不爱吃，因此对没吃过榴莲的人来说，反正榴莲没有毒，可以试一试，不好吃下次就不吃了，这叫试错。可不是说你拿个毒蘑菇啃一口，这不是试错，这是送命了。</p><p>因此回归到交易上来，止损只有你知道你在做什么的时候才是有效的，如果你都看不懂市场，随意进场，或者说止损完全没有逻辑，只不过是随便下浮多少点位就算止损了，那这不是止损，是送钱。</p><p>止损的方式分为三种，逻辑止损，策略止损和机制止损，分别对应不同的交易模式。这个在我之前的回答里有详细说明，感兴趣可以去翻看看，这里不再做详细描述。</p>',16)]))}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
